
.viewfinder {
  position: relative;
  width: 100%;
  max-width: 720px;
  margin: 0 auto;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  overflow: hidden;
}

/* 霜面裂痕层：状态 3 起出现，状态 4 最强 */
.viewfinder::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  background:
    linear-gradient(115deg, transparent 42%, rgb(232 213 196 / 10%) 43%, transparent 44%),
    linear-gradient(63deg, transparent 61%, rgb(232 213 196 / 8%) 62%, transparent 63%),
    linear-gradient(151deg, transparent 24%, rgb(232 213 196 / 6%) 25%, transparent 26%);
  transition: opacity 600ms ease;
}

.viewfinder.is-thawed::after {
  opacity: 1;
}

.viewfinder.is-live {
  border-color: var(--c-danger);
}

.focus-corner {
  position: absolute;
  width: 12px;
  height: 12px;
  border: 1px solid var(--c-primary);
  opacity: 0.5;
  pointer-events: none;
  transition: opacity 200ms;
}

.viewfinder.is-live .focus-corner {
  border-color: var(--c-danger);
  opacity: 0.9;
}

.focus-corner.tl {
  top: 5px;
  left: 5px;
  border-right: 0;
  border-bottom: 0;
}

.focus-corner.tr {
  top: 5px;
  right: 5px;
  border-left: 0;
  border-bottom: 0;
}

.focus-corner.bl {
  bottom: 5px;
  left: 5px;
  border-right: 0;
  border-top: 0;
}

.focus-corner.br {
  bottom: 5px;
  right: 5px;
  border-left: 0;
  border-top: 0;
}

.header {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 10px 14px 6px;
  background: transparent;
  border: 0;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.header:hover {
  background: rgb(205 214 224 / 4%);
}

.rec {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex: none;
  color: var(--c-danger);
  font-size: 10px;
  letter-spacing: 0.08em;
}

.rec em {
  font-style: normal;
}

.rec i {
  font-size: 7px;
}

.rec.live i {
  animation: blink 900ms steps(2, end) infinite;
}

@keyframes blink {
  50% {
    opacity: 0.15;
  }
}

.subject {
  display: flex;
  flex-direction: column;
  gap: 1px;
  flex: 1 1 auto;
  min-width: 0;
}

.subject-label {
  color: var(--c-text-muted);
  font-size: 9px;
  font-style: normal;
  letter-spacing: 0.14em;
}

.subject-name {
  font-size: 15px;
  letter-spacing: 0.06em;
}

.subject-stage {
  font-size: 11px;
  letter-spacing: 0.04em;
  transition: color 400ms ease;
}

.heat {
  display: grid;
  grid-template-columns: auto auto;
  align-items: baseline;
  gap: 0 6px;
  flex: none;
}

.heat-label {
  color: var(--c-text-muted);
  font-size: 10px;
  font-style: normal;
}

.heat-value {
  color: var(--c-affection);
  font-size: 17px;
  font-variant-numeric: tabular-nums;
}

.heat-track {
  grid-column: 1 / -1;
  position: relative;
  display: block;
  width: 86px;
  height: 3px;
  background: var(--c-border);
}

.heat-fill {
  position: absolute;
  inset: 0 auto 0 0;
  background: var(--c-affection);
  transition: width 200ms;
}

.is-live .heat-fill {
  background: var(--c-danger);
}

.is-thawed .heat-fill {
  transition: width 600ms cubic-bezier(0.22, 0.61, 0.36, 1);
}

.clock {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0;
  flex: none;
  font-variant-numeric: tabular-nums;
}

.clock-day {
  color: var(--c-text-muted);
  font-size: 9px;
  font-style: normal;
  letter-spacing: 0.1em;
}

.clock-date {
  color: var(--c-primary);
  font-size: 12px;
  font-weight: 400;
  letter-spacing: 0.02em;
}

.clock-time {
  color: var(--c-affection);
  font-size: 13px;
  letter-spacing: 0.04em;
}

.caret {
  flex: none;
  color: var(--c-text-muted);
  font-size: 11px;
  transition: transform 200ms;
}

.caret.up {
  transform: rotate(180deg);
}

.tools {
  display: flex;
  justify-content: flex-end;
  gap: 6px;
  padding: 0 14px 7px;
}

.ntr-switch,
.flip-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 8px;
  background: transparent;
  border: 1px solid var(--c-border);
  color: var(--c-text-muted);
  font: inherit;
  font-size: 10px;
  letter-spacing: 0.08em;
  cursor: pointer;
}

.ntr-switch em,
.flip-btn em {
  font-style: normal;
}

.ntr-switch:hover,
.flip-btn:hover {
  border-color: var(--c-primary);
  color: var(--c-primary);
}

.ntr-switch.on {
  border-color: var(--c-danger);
  background: rgb(229 72 77 / 14%);
  color: var(--c-danger);
}

.flip-btn {
  border-color: var(--c-thaw);
  color: var(--c-thaw);
}

.ntr-confirm {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 14px;
  background: rgb(229 72 77 / 10%);
  border-top: 1px solid rgb(229 72 77 / 35%);
  font-size: 11px;
}

.confirm-text {
  flex: 1 1 auto;
  color: var(--c-primary);
  line-height: 1.4;
}

.confirm-btn {
  flex: none;
  padding: 3px 9px;
  background: transparent;
  border: 1px solid var(--c-border);
  color: var(--c-text-muted);
  font: inherit;
  font-size: 11px;
  cursor: pointer;
}

.confirm-btn:hover {
  border-color: var(--c-primary);
  color: var(--c-primary);
}

.confirm-btn.primary {
  border-color: var(--c-affection);
  color: var(--c-affection);
}

.confirm-btn.primary:hover {
  background: rgb(143 184 216 / 16%);
}

.confirm-btn.primary.danger {
  border-color: var(--c-danger);
  color: var(--c-danger);
}

.confirm-btn.primary.danger:hover {
  background: rgb(229 72 77 / 18%);
}

.ntr-band {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 5px 14px;
  background: rgb(229 72 77 / 12%);
  border-top: 1px solid rgb(229 72 77 / 35%);
  color: var(--c-danger);
  font-size: 11px;
  letter-spacing: 0.03em;
}

.body {
  padding: 12px 14px 14px;
  border-top: 1px solid var(--c-border);
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 12px;
}

/* 情境切换：开关打开时红灯闪烁 */
.ntr-enter-active,
.ntr-leave-active {
  transition: opacity 200ms;
}

.ntr-enter-from,
.ntr-leave-to {
  opacity: 0;
}

/* 交互人格：硬切为主，解冻后转短渐显 */
.panel-enter-active,
.panel-leave-active {
  transition: opacity 120ms linear;
}

.is-thawed .panel-enter-active,
.is-thawed .panel-leave-active {
  transition: opacity 320ms ease;
}

.panel-enter-from,
.panel-leave-to {
  opacity: 0;
}
