
.block {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.block-head {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--c-text-muted);
  font-size: 10px;
  letter-spacing: 0.12em;
}

.block-head .range {
  margin-left: auto;
  font-size: 9px;
  font-style: normal;
  letter-spacing: 0.04em;
}

.meter {
  position: relative;
  height: 8px;
  background: var(--c-border);
  overflow: hidden;
}

.zero {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 1px;
  background: var(--c-text-muted);
  opacity: 0.8;
  z-index: 2;
}

.fill {
  position: absolute;
  top: 0;
  bottom: 0;
  background: var(--c-affection);
  transition: all 200ms;
}

.fill.negative {
  background: var(--c-warning);
}

.is-thawed .fill {
  transition: all 620ms cubic-bezier(0.22, 0.61, 0.36, 1);
}

.marker {
  position: absolute;
  top: -2px;
  bottom: -2px;
  width: 2px;
  background: var(--c-primary);
  transform: translateX(-1px);
  z-index: 3;
}

.scale {
  position: relative;
  height: 11px;
  color: var(--c-text-muted);
  font-size: 9px;
  font-variant-numeric: tabular-nums;
}

.scale span:first-child {
  float: left;
}

.scale span:last-child {
  float: right;
}

.scale-zero {
  position: absolute;
  transform: translateX(-50%);
}

.facts {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  margin: 0;
}

.facts > div {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.facts dt {
  color: var(--c-text-muted);
  font-size: 9px;
  letter-spacing: 0.06em;
}

.facts dd {
  margin: 0;
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}

.facts dd.capped {
  color: var(--c-warning);
}

.facts dd em {
  font-size: 9px;
  font-style: normal;
  opacity: 0.8;
}
