
.block {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.block-head {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--c-text-muted);
  font-size: 10px;
  letter-spacing: 0.12em;
}

.state-flag {
  margin-left: auto;
  padding: 1px 6px;
  border: 1px solid var(--c-border);
  font-size: 9px;
  font-style: normal;
  letter-spacing: 0.06em;
  transition: color 200ms, border-color 200ms;
}

.state-flag.excited {
  border-color: var(--c-thaw);
  color: var(--c-thaw);
}

.parts {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.part {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 7px 9px;
  background: var(--c-surface-raised);
  border-left: 2px solid var(--c-border);
  transition: border-color 300ms;
}

.part.excited {
  border-left-color: var(--c-thaw);
}

.part-name {
  font-size: 12px;
  letter-spacing: 0.06em;
}

.part-note {
  color: var(--c-primary);
  font-size: 10px;
  line-height: 1.5;
  opacity: 0.88;
}

.part.excited .part-note {
  color: var(--c-thaw);
  opacity: 0.95;
}

.sensitive {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 5px;
  padding-top: 2px;
}

.sensitive-label {
  color: var(--c-text-muted);
  font-size: 9px;
  font-style: normal;
  letter-spacing: 0.08em;
}

.spot {
  padding: 1px 6px;
  background: var(--c-border);
  color: var(--c-primary);
  font-size: 10px;
}

.verdict {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 7px 9px;
  background: rgb(232 213 196 / 8%);
  border-left: 2px solid var(--c-thaw);
}

.verdict-label {
  color: var(--c-text-muted);
  font-size: 9px;
  font-style: normal;
  letter-spacing: 0.08em;
}

.verdict-text {
  margin: 0;
  color: var(--c-thaw);
  font-size: 11px;
  line-height: 1.5;
}
