
.block {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.block-head {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--c-text-muted);
  font-size: 10px;
  letter-spacing: 0.12em;
}

.block-head .hint {
  margin-left: auto;
  font-size: 9px;
  font-style: normal;
  letter-spacing: 0.02em;
  opacity: 0.7;
}

.ladder {
  display: flex;
  flex-direction: column;
  gap: 0;
  margin: 0;
  padding: 0;
  list-style: none;
}

.rung {
  display: flex;
  gap: 8px;
  padding: 4px 0 4px 2px;
  opacity: 0.42;
  transition: opacity 300ms;
}

.rung.reached {
  opacity: 1;
}

.rung.current {
  background: rgb(143 184 216 / 8%);
}

.pip {
  flex: none;
  width: 6px;
  height: 6px;
  margin-top: 6px;
  background: var(--c-border);
}

.rung.reached .pip {
  background: var(--c-stage-2);
}

.rung:nth-child(2).reached .pip {
  background: var(--c-stage-1);
}

.rung:nth-child(4).reached .pip {
  background: var(--c-stage-3);
}

.rung:nth-child(5).reached .pip {
  background: var(--c-stage-4);
}

.rung.current .pip {
  box-shadow: 0 0 0 2px rgb(143 184 216 / 25%);
}

.rung-body {
  display: flex;
  flex-direction: column;
  gap: 0;
  min-width: 0;
}

.rung-name {
  font-size: 12px;
  letter-spacing: 0.03em;
}

.rung-cond {
  color: var(--c-text-muted);
  font-size: 10px;
}

.note {
  margin: 0;
  padding-top: 2px;
  color: var(--c-primary);
  font-size: 11px;
  opacity: 0.85;
}
