
.block {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.block-head {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--c-text-muted);
  font-size: 10px;
  letter-spacing: 0.12em;
}

.block-head .ep {
  margin-left: auto;
  font-size: 9px;
  font-style: normal;
  font-variant-numeric: tabular-nums;
}

.facts {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
  gap: 5px 10px;
  margin: 0;
}

.facts > div {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.facts dt {
  color: var(--c-text-muted);
  font-size: 9px;
  letter-spacing: 0.06em;
}

.facts dd {
  margin: 0;
  font-size: 11px;
}

.mono {
  font-variant-numeric: tabular-nums;
}

.accent {
  color: var(--c-affection);
}

.meters {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding-top: 2px;
  border-top: 1px solid var(--c-border);
}

.meter-row {
  display: flex;
  align-items: center;
  gap: 6px;
}

.meter-label {
  flex: none;
  width: 52px;
  color: var(--c-text-muted);
  font-size: 9px;
  letter-spacing: 0.06em;
}

.meter-bar {
  position: relative;
  flex: 1 1 auto;
  height: 4px;
  background: var(--c-border);
}

.meter-fill {
  position: absolute;
  inset: 0 auto 0 0;
  transition: width 200ms;
}

.meter-fill.heat {
  background: var(--c-affection);
}

.is-live .meter-fill.heat {
  background: var(--c-danger);
}

.meter-value {
  flex: none;
  min-width: 72px;
  color: var(--c-text-muted);
  font-size: 10px;
  font-style: normal;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.opinion {
  flex: 1 1 auto;
  font-size: 11px;
}

.opinion-good {
  color: var(--c-affection);
}

.opinion-idle {
  color: var(--c-primary);
}

.opinion-warn {
  color: var(--c-warning);
}

.opinion-bad {
  color: var(--c-danger);
}
