
.block {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.block-head {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--c-text-muted);
  font-size: 10px;
  letter-spacing: 0.12em;
}

.block-head .hint {
  margin-left: auto;
  font-size: 9px;
  font-style: normal;
  letter-spacing: 0.02em;
  opacity: 0.7;
}

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.guest {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 7px 9px;
  background: var(--c-surface-raised);
  border-left: 2px solid var(--c-affection);
}

.guest.intimate {
  border-left-color: var(--c-thaw);
}

.guest-top {
  display: flex;
  align-items: baseline;
  gap: 6px;
}

.guest-name {
  font-size: 12px;
  letter-spacing: 0.04em;
}

.guest-tag {
  color: var(--c-text-muted);
  font-size: 9px;
}

.guest-state {
  display: flex;
  align-items: center;
  gap: 5px;
  color: var(--c-primary);
  font-size: 11px;
}

.guest-state i {
  font-size: 10px;
  color: var(--c-affection);
}

.guest.intimate .guest-state i {
  color: var(--c-thaw);
}

.guest-affection {
  display: flex;
  align-items: center;
  gap: 6px;
}

.aff-label {
  flex: none;
  color: var(--c-text-muted);
  font-size: 9px;
  letter-spacing: 0.06em;
}

.aff-bar {
  position: relative;
  flex: 1 1 auto;
  height: 3px;
  background: var(--c-border);
}

.aff-fill {
  position: absolute;
  inset: 0 auto 0 0;
  background: var(--c-affection);
  transition: width 200ms;
}

.guest.intimate .aff-fill {
  background: var(--c-thaw);
}

.aff-value {
  flex: none;
  color: var(--c-text-muted);
  font-size: 10px;
  font-style: normal;
  font-variant-numeric: tabular-nums;
}
